'use strict';
/**
 * Test Suite: Panda Hive Dynamic Engine & Interactivity Verification
 *
 * Verifies that all projects generated by Panda Hive agents are guaranteed
 * 100% dynamic, functional, and interactive:
 * 1. Automatic script injection (<script src="app.js" defer></script>)
 * 2. Automatic CSS injection (<link rel="stylesheet" href="style.css">)
 * 3. Dynamic runtime styles appended (.ph-toast-container, .ph-cart-drawer)
 * 4. Reactive State, Live Search, Cart Drawer & Event Delegation injected
 * 5. Sanitization of broken LLM syntax (unescaped join newlines)
 * 6. Verification of workspace/tools/ as a live dynamic project
 */

const assert = require('node:assert');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const ts = require('typescript');

// Transpile dynamicEngine.ts directly to CommonJS for clean testing
const engineSrc = fs.readFileSync(path.join(__dirname, '..', 'src', 'main', 'dynamicEngine.ts'), 'utf8');
const engineJs = ts.transpileModule(engineSrc, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 }
}).outputText;

const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'hive-dynamic-test-'));
fs.writeFileSync(path.join(tempDir, 'dynamicEngine.js'), engineJs, 'utf8');

const { generateDynamicEngine, ensureProjectIsDynamic, getFallbackUIFiles } = require(path.join(tempDir, 'dynamicEngine.js'));

async function runTests() {
  console.log('=== PANDA HIVE DYNAMIC ENGINE & INTERACTIVITY TESTS ===\n');
  let passed = 0;
  let failed = 0;

  function test(name, fn) {
    try {
      fn();
      console.log(`  ✔ [PASS] ${name}`);
      passed++;
    } catch (err) {
      console.error(`  ✖ [FAIL] ${name}`);
      console.error(`     Error: ${err.message}\n`);
      failed++;
    }
  }

  // Test 1: Injects missing <script src="app.js"> into index.html
  test('Test 1: Auto-injects <script src="app.js" defer></script> into index.html', () => {
    const projDir = path.join(tempDir, 'proj-1');
    fs.mkdirSync(projDir, { recursive: true });
    fs.writeFileSync(path.join(projDir, 'index.html'), '<!DOCTYPE html><html><head><title>Test</title></head><body><h1>Hello</h1></body></html>', 'utf8');
    fs.writeFileSync(path.join(projDir, 'style.css'), 'body { background: #fff; }', 'utf8');

    ensureProjectIsDynamic(projDir, 'proj-1', 'Build a task dashboard');

    const html = fs.readFileSync(path.join(projDir, 'index.html'), 'utf8');
    assert(html.includes('<script src="app.js" defer></script>'), 'Missing app.js script tag');
    assert(html.includes('style.css'), 'Missing style.css link tag');
  });

  // Test 2: Injects missing style.css link into index.html
  test('Test 2: Auto-injects <link rel="stylesheet" href="style.css"> into <head>', () => {
    const projDir = path.join(tempDir, 'proj-2');
    fs.mkdirSync(projDir, { recursive: true });
    fs.writeFileSync(path.join(projDir, 'index.html'), '<!DOCTYPE html><html><head><title>No CSS</title></head><body><p>Test</p></body></html>', 'utf8');

    ensureProjectIsDynamic(projDir, 'proj-2', 'Build an online store');

    const html = fs.readFileSync(path.join(projDir, 'index.html'), 'utf8');
    assert(html.includes('<link rel="stylesheet" href="style.css">'), 'Missing style.css in head');
  });

  // Test 3: Creates app.js with dynamic engine if missing
  test('Test 3: Generates full reactive dynamic engine in app.js if file is missing', () => {
    const projDir = path.join(tempDir, 'proj-3');
    fs.mkdirSync(projDir, { recursive: true });
    fs.writeFileSync(path.join(projDir, 'index.html'), '<!DOCTYPE html><html><body>Content</body></html>', 'utf8');

    ensureProjectIsDynamic(projDir, 'proj-3', 'Build a crypto tracker');

    assert(fs.existsSync(path.join(projDir, 'app.js')), 'app.js was not created');
    const js = fs.readFileSync(path.join(projDir, 'app.js'), 'utf8');
    assert(js.includes('__PANDA_HIVE_DYNAMIC_ENGINE__'), 'app.js does not contain dynamic engine');
    assert(js.includes('phToast'), 'app.js missing toast notification system');
    assert(js.includes('setupLiveSearch'), 'app.js missing live search handler');
    assert(js.includes('setupActionDelegation'), 'app.js missing action event delegation');
  });

  // Test 4: Appends dynamic engine & sanitizes broken syntax in existing app.js
  test('Test 4: Sanitizes broken LLM strings and appends self-healing dynamic engine', () => {
    const projDir = path.join(tempDir, 'proj-4');
    fs.mkdirSync(projDir, { recursive: true });
    fs.writeFileSync(path.join(projDir, 'index.html'), '<!DOCTYPE html><html><body><h1>App</h1></body></html>', 'utf8');
    // Simulate broken LLM output: join("\n") split across lines with invalid string literal
    const brokenJs = `
      function render() {
        return ["a", "b"].join("
");
      }
    `;
    fs.writeFileSync(path.join(projDir, 'app.js'), brokenJs, 'utf8');

    ensureProjectIsDynamic(projDir, 'proj-4', 'Shopping site');

    const fixedJs = fs.readFileSync(path.join(projDir, 'app.js'), 'utf8');
    assert(!fixedJs.includes('.join("\n")'), 'Broken join was not sanitized');
    assert(fixedJs.includes('__PANDA_HIVE_DYNAMIC_ENGINE__'), 'Dynamic engine was not appended');
  });

  // Test 5: Appends modern toast & drawer styling to style.css
  test('Test 5: Injects .ph-toast-container and .ph-cart-drawer styles into style.css', () => {
    const projDir = path.join(tempDir, 'proj-5');
    fs.mkdirSync(projDir, { recursive: true });
    fs.writeFileSync(path.join(projDir, 'style.css'), '/* Original styles */\nh1 { color: blue; }\n', 'utf8');

    ensureProjectIsDynamic(projDir, 'proj-5', 'Store');

    const css = fs.readFileSync(path.join(projDir, 'style.css'), 'utf8');
    assert(css.includes('.ph-toast-container'), 'Missing toast styling');
    assert(css.includes('.ph-cart-drawer'), 'Missing cart drawer styling');
    assert(css.includes('.ph-drawer-overlay'), 'Missing drawer overlay styling');
  });

  // Test 6: Verify workspace/tools/ project is 100% dynamic
  test('Test 6: Apply ensureProjectIsDynamic to workspace/tools/ and verify live readiness', () => {
    const toolsDir = path.join(__dirname, '..', 'workspace', 'tools');
    if (fs.existsSync(toolsDir)) {
      ensureProjectIsDynamic(toolsDir, 'tools', 'Shop powerful computers and accessories');

      const html = fs.readFileSync(path.join(toolsDir, 'index.html'), 'utf8');
      const css = fs.readFileSync(path.join(toolsDir, 'style.css'), 'utf8');
      const js = fs.readFileSync(path.join(toolsDir, 'app.js'), 'utf8');

      assert(html.includes('<script src="app.js" defer></script>'), 'tools index.html missing script');
      assert(css.includes('.ph-toast-container'), 'tools style.css missing toast container');
      assert(js.includes('__PANDA_HIVE_DYNAMIC_ENGINE__'), 'tools app.js missing dynamic engine');
    }
  });

  // Test 7: Verify Sports Management domain fallback layout
  test('Test 7: Generates authentic Sports Management portal (fixtures, turf, rosters, no Compute Engine)', () => {
    const res = getFallbackUIFiles('sport-management', 'create sport management website');
    assert(res.html.includes('sports-theme'), 'Missing sports-theme class');
    assert(res.html.includes('Arsenal FC vs Chelsea FC'), 'Missing headline sports match');
    assert(res.html.includes('AstroTurf Arena'), 'Missing turf booking feature');
    assert(res.html.includes('₹'), 'Missing Indian Rupee currency format');
    assert(!res.html.includes('Real-Time Compute Engine'), 'Generic compute engine was incorrectly included!');
    assert(!res.html.includes('$249.00'), 'Fake hosting price $249 was included!');
  });

  // Test 8: Verify Health & Hospital Management domain fallback layout
  test('Test 8: Generates authentic Clinical Health portal (doctors, vitals, ICU, no Compute Engine)', () => {
    const res = getFallbackUIFiles('health-management', 'create health management system');
    assert(res.html.includes('health-theme'), 'Missing health-theme class');
    assert(res.html.includes('Dr. Sarah Jenkins'), 'Missing doctor appointment card');
    assert(res.html.includes('ICU Beds Online'), 'Missing ICU bed tracker');
    assert(res.html.includes('₹'), 'Missing Indian Rupee currency format');
    assert(!res.html.includes('Real-Time Compute Engine'), 'Generic compute engine was incorrectly included!');
    assert(!res.html.includes('$249.00'), 'Fake hosting price $249 was included!');
  });

  // Test 9: Verify Generic Fallback no longer has fake $249 Compute Engine
  test('Test 9: Generic fallback produces clean operational modules without $249 Compute Engine', () => {
    const res = getFallbackUIFiles('enterprise-core', 'build enterprise workflow');
    assert(res.html.includes('Active Modules'), 'Missing Active Modules header');
    assert(!res.html.includes('Real-Time Compute Engine'), 'Generic compute engine was incorrectly included!');
    assert(!res.html.includes('$249.00'), 'Fake hosting price $249 was included!');
  });

  console.log(`\nAll Dynamic Engine tests completed: ${passed} passed, ${failed} failed.\n`);
  if (failed > 0) {
    process.exit(1);
  }
}

runTests();
